<script setup>
import {ref,onMounted,watch} from 'vue';import PageHeader from '../../components/common/PageHeader.vue';import StatusView from '../../components/common/StatusView.vue';import {getProducts} from '../../api/catalog.js'
const category=ref('');const style=ref('');const items=ref([]);const loading=ref(true)
async function load(){loading.value=true;items.value=(await getProducts({category:category.value,style:style.value})).data;loading.value=false}onMounted(load);watch([category,style],load)
</script>
<template><div class="page-shell"><div class="container"><PageHeader title="产品中心" description="从空间功能、柜体风格与材料质感出发，找到适合您的组合。" :breadcrumbs="['首页','产品中心']"/><div class="filter-bar"><el-select v-model="category" placeholder="全部空间" clearable style="width:150px"><el-option v-for="x in ['厨房','餐厅','卧室','客厅','玄关','书房']" :key="x" :label="x" :value="x"/></el-select><el-select v-model="style" placeholder="全部风格" clearable style="width:150px"><el-option v-for="x in ['现代欧式','法式简约']" :key="x" :label="x" :value="x"/></el-select><span class="muted">共 {{items.length}} 个系列</span></div><StatusView v-if="loading" type="loading" description="正在整理产品系列"/><StatusView v-else-if="!items.length" title="暂无匹配产品" description="请尝试调整筛选条件"/><div v-else class="editorial-grid catalog-grid"><router-link v-for="item in items" :key="item.id" :to="`/products/${item.id}`" class="editorial-card"><div class="editorial-card__image"><img :src="item.image" :alt="item.name"></div><h3>{{item.name}}</h3><p class="muted">{{item.category}} · {{item.material}}</p></router-link></div></div></div></template>
<style scoped>.catalog-grid{padding-top:28px}.editorial-card p{margin:0}</style>
